BEGIN
    IF (
        SELECT IFNULL(journal_entry.source, '')
        FROM journal_entry
        WHERE journal_entry.id = NEW.journal_entry_id
        LIMIT 1
    ) = '' THEN
        CALL gl_post_journal_entry(NEW.journal_entry_id);
    END IF;
END

